SELECT?course
WHERE {
  ?course a ns1:course.
  ?course ns1:has_research_group ns1:computer_system_laboratory.
}

SELECT?group
WHERE {
  { SELECT?group (COUNT(?course) AS?COUNT) WHERE {?course a ns1:course.?course ns1:has_research_group?group.} GROUP BY?group }
  FILTER NOT EXISTS { SELECT?otherGroup (COUNT(?otherCourse) AS?otherCount) WHERE {?otherCourse a ns1:course.?otherCourse ns1:has_research_group?otherGroup.} GROUP BY?otherGroup having (?otherCount >?COUNT) }
}
LIMIT 1

